import { MoveInput, validateMove } from '../chess-input/chess-input.ts';

export interface Move {
  fromRank: number;
  fromFile: string;
  toRank: number;
  toFile: string;
}

export interface MoveResult {
  isValid: boolean;
  message?: string;
}

export class MoveGenerator {
  private board: string[][];

  constructor(board: string[][]) {
    this.board = board;
  }

  public async generateMoves(): Promise<Move[]> {
    const moves: Move[] = [];
    for (let rank = 1; rank <= 8; rank++) {
      for (let file = 'a'; file <= 'h'; file++) {
        const piece = this.board[rank - 1][file.charCodeAt(0) - 'a'.charCodeAt(0)];
        if (!piece) continue;
        const legalMoves = this.getLegalMoves(rank, file);
        for (const move of legalMoves) {
          moves.push(move);
        }
      }
    }
    return moves;
  }

  private getLegalMoves(rank: number, file: string): Move[] {
    const moves: Move[] = [];
    const piece = this.board[rank - 1][(file.charCodeAt(0) - 'a'.charCodeAt(0))];
    if (piece === 'P') {
      if (rank === 2) {
        moves.push({ fromRank: rank, fromFile: file, toRank: rank + 2, toFile: file });
      }
      moves.push({ fromRank: rank, fromFile: file, toRank: rank + 1, toFile: file });
      if (file.charCodeAt(0) - 'a'.charCodeAt(0) > 0) {
        const target = this.board[rank + 1][(file.charCodeAt(0) - 'a'.charCodeAt(0)) - 1];
        if (target && target === 'p') {
          moves.push({ fromRank: rank, fromFile: file, toRank: rank + 1, toFile: String.fromCharCode((file.charCodeAt(0) - 'a'.charCodeAt(0)) - 1) });
        }
      }
      if (file.charCodeAt(0) - 'a'.charCodeAt(0) < 7) {
        const target = this.board[rank + 1][(file.charCodeAt(0) - 'a'.charCodeAt(0)) + 1];
        if (target && target === 'p') {
          moves.push({ fromRank: rank, fromFile: file, toRank: rank + 1, toFile: String.fromCharCode((file.charCodeAt(0) - 'a'.charCodeAt(0)) + 1) });
        }
      }
    }
    return moves;
  }

  private isCheckmate(): boolean {
    return false;
  }

  public async validateMove(move: Move): Promise<MoveResult> {
    const { fromRank, fromFile, toRank, toFile } = move;
    if (!/^[a-h][1-8]$/i.test(fromFile) || fromRank < 1 || fromRank > 8) {
      return { isValid: false, message: 'Invalid from position' };
    }
    if (!/^[a-h][1-8]$/i.test(toFile) || toRank < 1 || toRank > 8) {
      return { isValid: false, message: 'Invalid to position' };
    }
    return { isValid: true };
  }

  public async makeMove(move: Move): Promise<void> {
    const { fromRank, fromFile, toRank, toFile } = move;
    const from = this.board[fromRank - 1][(fromFile.charCodeAt(0) - 'a'.charCodeAt(0))];
    this.board[fromRank - 1][(fromFile.charCodeAt(0) - 'a'.charCodeAt(0))] = null;
    this.board[toRank - 1][(toFile.charCodeAt(0) - 'a'.charCodeAt(0))] = from;
  }
}

