export function dataStore() {
  const savedGames: { id: number; name: string; moves: string[] }[] = [];
  let currentGameId = 1;
  let currentGameMoves: string[] = [];
  let currentPlayer: 'white' | 'black' = 'white';

  function saveGame(name: string) {
    savedGames.push({ id: currentGameId, name, moves: currentGameMoves.slice() });
    currentGameId++;
    currentGameMoves = [];
    currentPlayer = 'white';
  }

  function loadGame(id: number) {
    const game = savedGames.find((g) => g.id === id);
    if (game) {
      currentGameMoves = game.moves.slice();
      currentPlayer = game.moves.length % 2 === 0 ? 'white' : 'black';
    }
  }

  function makeMove(move: string) {
    currentGameMoves.push(move);
    currentPlayer = currentPlayer === 'white' ? 'black' : 'white';
  }

  function getMoves() { return currentGameMoves; }
  function getCurrentPlayer() { return currentPlayer; }
  function getSavedGames() { return savedGames; }

  return { saveGame, loadGame, makeMove, getMoves, getCurrentPlayer, getSavedGames };
}

interface Fibonacci {
  n: number;
}

let _fibCache = new Map<number, number>();

export function fib(n: number): number {
  if (n < 0) {
    throw new Error("Negative argument provided");
  }

  if (_fibCache.has(n)) {
    return _fibCache.get(n)!;
  }

  if (n === 0) {
    return 0;
  }

  const result = fib(n - 1) + fib(n - 2);

  _fibCache.set(n, result);
  return result;
}

export function fibSequence(n: number): number[] {
  const sequence: number[] = [];

  for (let i = 0; i < n; i++) {
    sequence.push(fib(i));
  }

  return sequence;
}

