  function updateTimer(): void {
    if (isRunning) {
      elapsedTime += Date.now() - (startTime ?? Date.now());
      startTime = Date.now();
    }

    const minutes = Math.floor(elapsedTime / 60000);
    const seconds = ((elapsedTime % 60000) / 1000).toFixed(2);

    timerDisplay.textContent = `${String(minutes).padStart(2, '0')}:${seconds.padEnd(5, '0')}`;

    requestAnimationFrame(updateTimer);
  }

  startPauseButton.addEventListener('click', () => {
    if (isRunning) {
      isRunning = false;
      startTime = null;
      timerDisplay.textContent = '';
    } else {
      isRunning = true;
      updateTimer();
    }
  });
}

