class PomodoroTimer {
  private isRunningValue = false;
  private startTime = Date.now();
  private pausedTime = 0;

  start() {
    this.isRunningValue = true;
    this.startTime = Date.now();
    this.pausedTime = 0;
  }

  pause() {
    if (this.isRunning()) {
      this.isRunningValue = false;
      this.pausedTime += Date.now() - this.startTime;
    }
  }

  reset() {
    this.isRunningValue = false;
    this.startTime = Date.now();
    this.pausedTime = 0;
  }

  getElapsed(): number {
    if (this.isRunning()) {
      return Date.now() - this.startTime + this.pausedTime;
    } else {
      return this.pausedTime;
    }
  }

  isRunning(): boolean {
    return this.isRunningValue;
  }
}

export function handleInput(inputData: InputData): StateAndEvents {
  const timer = new PomodoroTimer();

  switch (inputData.action) {
    case 'start':
      timer.start();
      return { state: { status: 'running', elapsedTime: 0 }, events: ['timerStarted'] };

    case 'pause':
      if (timer.isRunning()) {
        timer.pause();
        return { state: { status: 'paused', elapsedTime: timer.getElapsed() }, events: ['timerPaused'] };
      }
      break;

    case 'reset':
      timer.reset();
      return { state: { status: 'idle', elapsedTime: 0 }, events: ['timerReset'] };

    default:
      throw new Error('Unknown action');
  }

  return null; // unreachable
}

