export class TimerCore {
  private dataStore: DataStore;

  constructor(dataStore: DataStore) {
    this.dataStore = dataStore;
  }

  startTimer(duration: number): void {
    const currentTime = new Date().getTime();
    const endTime = currentTime + duration * 60 * 1000;

    // Store the timer state in the data store
    this.dataStore.setData('timer', { startTime: currentTime, endTime });

    console.log(`Timer started. Duration: ${duration} minutes`);
  }

  stopTimer(): void {
    const currentData = this.dataStore.getData('timer');
    if (!currentData) {
      console.log('No active timer to stop.');
      return;
    }

    // Remove the timer state from the data store
    this.dataStore.setData('timer', null);

    console.log(`Timer stopped.`);
  }

  resetTimer(): void {
    const currentData = this.dataStore.getData('timer');
    if (!currentData) {
      console.log('No active timer to reset.');
      return;
    }

    // Reset the timer state in the data store
    this.dataStore.setData('timer', { startTime: null, endTime: null });

    console.log(`Timer reset.`);
  }

  getElapsedTime(): number | null {
    const currentData = this.dataStore.getData('timer');
    if (!currentData) {
      return null;
    }

    // Calculate elapsed time
    const currentTime = new Date().getTime();
    const elapsedTime = (currentTime - currentData.startTime!) / 1000; // Convert to seconds

    return Math.round(elapsedTime);
  }

  getRemainingTime(): number | null {
    const currentData = this.dataStore.getData('timer');
    if (!currentData) {
      return null;
    }

    // Calculate remaining time
    const currentTime = new Date().getTime();
    const remainingTime = (currentData.endTime! - currentTime) / 1000; // Convert to seconds

    return Math.round(remainingTime);
  }

  isTimerActive(): boolean {
    const currentData = this.dataStore.getData('timer');
    if (!currentData || !currentData.startTime) {
      return false;
    }

    // Check if timer has started
    return true;
  }
}

