export class AIOpponent {
  private gameState: GameState;

  constructor(gameState: GameState) {
    this.gameState = gameState;
  }

  public makeMove(boardSize: number): [number, number] | null {
    // Check for available moves
    const emptyCells = [];
    for (let row = 0; row < boardSize; row++) {
      for (let col = 0; col < boardSize; col++) {
        if (!this.gameState.board[row][col]) {
          emptyCells.push([row, col]);
        }
      }
    }

    // If no moves available, return null
    if (emptyCells.length === 0) {
      return null;
    }

    // Choose a random move from the available cells
    const randomIndex = Math.floor(Math.random() * emptyCells.length);
    const [row, col] = emptyCells[randomIndex];

    // Make the move and check for winner or full board
    this.gameState.board[row][col] = 'O';
    if (this.checkWinner(this.gameState.board) || this.isBoardFull(this.gameState.board)) {
      return null;
    }

    return [row, col];
  }
}

