// Define a GameEngine class to handle the logic of the game.
class GameEngine {
  private gameState: GameState;

  constructor() {
    this.gameState = new GameState();
  }

  // Check if the game is over (win or draw).
  public checkGameOver(): boolean {
    const board = this.gameState.getBoard();

    // Check rows for a win
    for (let row = 0; row < 3; row++) {
      if (board[row][0] !== '' && board[row][0] === board[row][1] && board[row][0] === board[row][2]) {
        return true;
      }
    }

    // Check columns for a win
    for (let col = 0; col < 3; col++) {
      if (board[0][col] !== '' && board[0][col] === board[1][col] && board[0][col] === board[2][col]) {
        return true;
      }
    }

    // Check diagonals for a win
    if ((board[0][0] !== '' && board[0][0] === board[1][1] && board[0][0] === board[2][2])
     || (board[0][2] !== '' && board[0][2] === board[1][1] && board[0][2] === board[2][0])) {
      return true;
    }

    // Check for a draw
    for (let row = 0; row < 3; row++) {
      if (board[row].includes('')) {
        return false;
      }
    }

    return true;
  }

  // Get the current board state.
  public getBoardState(): string[][] {
    return this.gameState.getBoard();
  }
}

// Define a GameController class to handle user input and game logic.
class GameController {
  private gameEngine: GameEngine;

  constructor() {
    this.gameEngine = new GameEngine();
  }

  // Handle the player's move on the board.
  public makeMove(row: number, col: number): boolean {
    const boardState = this.gameEngine.getBoardState();

    if (boardState[row][col] === '') {
      // Update the board with the player's move
      boardState[row][col] = 'X';

      // Check for a win or draw after each move
      if (this.gameEngine.checkGameOver()) {
        console.log('Game Over');
        return true;
      }

      // Make AI opponent move
      const aiOpponent = new AIOpponent();
      aiOpponent.makeMove();

      // Check again after the AI's turn
      return this.gameEngine.checkGameOver();
    } else {
      console.log('Cell already taken, choose another one.');
      return false;
    }
  }

  // Restart the game.
  public restartGame(): void {
    const boardState = this.gameEngine.getBoardState();

    for (let row = 0; row < 3; row++) {
      for (let col = 0; col < 3; col++) {
        boardState[row][col] = '';
      }
    }

    console.log('Game restarted');
  }
}

