export class FileIndex {
  private files: Map<string, string>;

  constructor() {
    this.files = new Map();
  }

  addFile(path: string, content: string): void {
    if (this.files.has(path)) {
      throw new Error(`File already exists at ${path}`);
    }
    this.files.set(path, content);
  }

  deleteFile(path: string): void {
    if (!this.files.delete(path)) {
      throw new Error(`No file found at ${path}`);
    }
  }

  renameFile(oldPath: string, newPath: string): void {
    const content = this.files.get(oldPath);
    if (content === undefined) {
      throw new Error(`No file found at ${oldPath}`);
    }
    this.deleteFile(oldPath);
    this.addFile(newPath, content);
  }

  readFile(path: string): string | null {
    return this.files.get(path) || null;
  }

  listFiles(): { path: string; size: number }[] {
    const result = [];
    for (const [path, content] of this.files.entries()) {
      result.push({ path, size: content.length });
    }
    return result;
  }

  search(pattern: string): { path: string; snippet?: string }[] {
    const regex = new RegExp(`\\b${pattern}\\b`, 'i');
    const matches = [];
    for (const [path, content] of this.files.entries()) {
      if (regex.test(content)) {
        matches.push({ path });
      }
    }
    return matches;
  }

  getStats(): { fileCount: number; totalSizeBytes: number } {
    let sizeBytes = 0;
    for (const [, content] of this.files) {
      sizeBytes += content.length;
    }
    return { fileCount: this.files.size, totalSizeBytes: sizeBytes };
  }

  clearAll(): void {
    this.files.clear();
  }
}

