export function makeMove(board: string[][], row: number, col: number): void {
  if (row < 0 || row >= board.length || col < 0 || col >= board[row].length) {
    throw new Error('Invalid move');
  }

  // Check for an empty space at the given position
  if (board[row][col] !== '') {
    throw new Error('Space already taken');
  }

  // Place a piece on the board
  const player = 'X'; // X always goes first in tic-tac-toe
  board[row][col] = player;
}

export function checkWinner(board: string[][]): string | null {
  // Check rows for a winner
  for (let i = 0; i < board.length; i++) {
    if (
      board[i][0] !== '' &&
      board[i][0] === board[i][1] &&
      board[i][1] === board[i][2]
    ) {
      return board[i][0];
    }
  }

  // Check columns for a winner
  for (let j = 0; j < board.length; j++) {
    if (
      board[0][j] !== '' &&
      board[0][j] === board[1][j] &&
      board[1][j] === board[2][j]
    ) {
      return board[0][j];
    }
  }

  // Check diagonals for a winner
  if (
    (board[0][0] !== '' && board[0][0] === board[1][1] && board[1][1] === board[2][2]) ||
    (board[0][2] !== '' && board[0][2] === board[1][1] && board[1][1] === board[2][0])
  ) {
    return board[1][1];
  }

  // No winner found
  return null;
}

export function isDraw(board: string[][]): boolean {
  for (let i = 0; i < board.length; i++) {
    for (let j = 0; j < board[i].length; j++) {
      if (board[i][j] === '') {
        return false;
      }
    }
  }

  // All spaces are filled, and there is no winner
  return true;
}

