import { FileIndex } from '../file-index/file-index.ts';

export class FileListView {
  private container: HTMLElement;
  private fileIndex: FileIndex;

  constructor(containerId: string) {
    this.container = document.getElementById(containerId)!;
    this.fileIndex = new FileIndex();
  }

  async render() {
    const files = await this.fileIndex.getFiles();

    const fileListContainer = document.createElement('div');
    fileListContainer.className = 'file-list-container';

    if (files.length === 0) {
      const emptyMessage = document.createElement('p');
      emptyMessage.textContent = 'No files found.';
      fileListContainer.appendChild(emptyMessage);
    } else {
      for (const file of files) {
        const fileItem = this.createFileItem(file.name, file.size);
        fileListContainer.appendChild(fileItem);
      }
    }

    this.container.innerHTML = '';
    this.container.appendChild(fileListContainer);

    // Add event listeners
    document.getElementById('add-file-btn')?.addEventListener('click', async () => {
      const fileNameInput = document.querySelector<HTMLInputElement>('#file-name-input');
      if (fileNameInput && fileNameInput.value.trim() !== '') {
        await this.fileIndex.addFile(fileNameInput.value);
        this.render();
      }
    });

    document.querySelectorAll('.delete-btn').forEach((btn) =>
      btn.addEventListener('click', async () => {
        const fileId = parseInt(btn.dataset.id!);
        if (!isNaN(fileId)) {
          await this.fileIndex.deleteFileById(fileId);
          this.render();
        }
      })
    );
  }

  private createFileItem(name: string, size: number): HTMLElement {
    const fileItem = document.createElement('div');
    fileItem.className = 'file-item';

    // File name
    const fileNameSpan = document.createElement('span');
    fileNameSpan.textContent = `${name} (${size / (1024 * 1024) > 1 ? Math.round(size / (1024 * 1024)) + ' MB' : size / 1024 + ' KB'})`;
    fileItem.appendChild(fileNameSpan);

    // Delete button
    const deleteBtn = document.createElement('button');
    deleteBtn.textContent = 'Delete';
    deleteBtn.className = 'delete-btn';
    deleteBtn.dataset.id = name;
    fileItem.appendChild(deleteBtn);

    return fileItem;
  }
}

