  return { state };
}

import { Grid } from '../grid-input/grid-input';

export interface GameRequest {
  grid: Grid;
  player: 'X' | 'O';
}

export interface MinimaxResult {
  bestMove: number;
  score: number;
}

function isWin(grid: string[], player: 'X' | 'O'): boolean {
  const winningLines = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6]
  ];
  return winningLines.some(line =>
    line.every(index => grid[index] === player)
  );
}

function isDraw(grid: string[]): boolean {
  return grid.every(cell => cell !== '');
}

function evaluate(grid: string[], player: 'X' | 'O'): number {
  if (isWin(grid, player)) return 1;
  if (isDraw(grid)) return 0;
  return -1;
}

export function minimax(request: GameRequest): MinimaxResult {
  let bestMove = -1;
  let bestScore = -Infinity;
  const { grid, player } = request;

  for (let i = 0; i < grid.cells.length; i++) {
    if (grid.cells[i] !== '') continue;
    const newGrid = grid.cells.slice();
    newGrid[i] = player;
    const score = evaluate(newGrid, player);
    if (score > bestScore) {
      bestScore = score;
      bestMove = i;
    }
  }

  return { bestMove, score: bestScore };
}

