import { MinimaxResult } from '../minimax-ai/minimax-ai';

/**
 * Checks for a win or tie in a tic-tac-toe game.
 * - If a player has won, returns the winning player ('X' or 'O').
 * - If the game is a tie, returns 'Tie'.
 * - Otherwise, returns 'ongoing'.
 * @param result - MinimaxResult object containing the best move and score.
 * @returns 'X' | 'O' | 'Tie' | 'ongoing'
 */
export function checkWin(result: MinimaxResult): 'X' | 'O' | 'Tie' | 'ongoing' {
  if (result.score === 1) {
    return 'X';
  }
  if (result.score === -1) {
    return 'O';
  }
  if (result.score === 0) {
    return 'Tie';
  }
  return 'ongoing';
}

#include <stdio.h>
