typedef struct {
    int line_count;
    int word_count;
    int char_count;
} WordCount;

WordCount count_words(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    int line_count = 0;
    int word_count = 0;
    int char_count = 0;
    bool in_word = false;

