        char_count++;
        if (ch == '\n') {
            line_count++;
        }
        if (isspace(ch)) {
            in_word = false;
        } else {
            if (!in_word) {
                word_count++;
                in_word = true;
            }
        }
    }

    fclose(file);
    return (WordCount){line_count, word_count, char_count};
}

