#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure to hold word counts
typedef struct {
    int line_count;
    int word_count;
    int char_count;
} WordCounts;

// Function to count words in a string
int count_words(const char *str) {
    int word_count = 0;
    int in_word = 0;
    for (size_t i = 0; i < strlen(str); i++) {
        if (str[i] == ' ' || str[i] == '\t' || str[i] == '\n') {
            in_word = 0;
        } else {
            if (!in_word) {
                word_count++;
                in_word = 1;
            }
        }
    }
    return word_count;
}

// Function to count lines in a string
int count_lines(const char *str) {
    int line_count = 0;
    for (size_t i = 0; i < strlen(str); i++) {
        if (str[i] == '\n') {
            line_count++;
        }
    }
    return line_count;
}

// Function to count characters in a string
int count_chars(const char *str) {
    return (int)strlen(str);
}

// Function to read a file and count its lines, words, and characters
int read_file_and_count(const char *filename, WordCounts *counts) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    char buffer[4096];
    size_t bytesRead;
    int total_chars = 0;

    counts->line_count = 0;
    counts->word_count = 0;
    counts->char_count = 0;

    while ((bytesRead = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        total_chars += bytesRead;
        counts->line_count += count_lines(buffer);
        counts->word_count += count_words(buffer);
    }

    counts->char_count = total_chars;

    fclose(file);
    return 0;
}

// Function to print the word counts
void print_word_counts(const WordCounts *counts) {
    printf("Lines: %d\n", counts->line_count);
    printf("Words: %d\n", counts->word_count);
    printf("Characters: %d\n", counts->char_count);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    WordCounts counts;
    if (read_file_and_count(argv[1], &counts) == -1) {
        return 1;
    }

    print_word_counts(&counts);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024

typedef struct {
    int lines;
    int words;
    int characters;
} WordCount;

WordCount count_words(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    WordCount count = {0};
    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        count.lines++;
        count.characters += strlen(line);
        char *token = strtok(line, " \t\n");
        while (token) {
            count.words++;
            token = strtok(NULL, " \t\n");
        }
    }

    fclose(file);
    return count;
}

void print_report(const WordCount *count) {
    printf("Lines: %d\n", count->lines);
    printf("Words: %d\n", count->words);
    printf("Characters: %d\n", count->characters);
}

